#include <stdio.h>
#include <pthread.h>
#define MAX_THREADS 4
int N;
int prime_arr[50];
void *printprime()
{
    int i, j, flag;
    for (i = 2; i < N; i++)
    {
        flag = 0;
        for (j = 2; j <= i / 2; j++)
        {
            if (i % j == 0)
            {
                flag = 1;
                break;
            }
        }
        if (flag == 0) prime_arr[i] = 1;
    }
}

int main(int args, char *argv[])
{
    pthread_t tid=NULL;
    int count;

    N = atoi(argv[1]);
    printf("CREATING THREAD\n");
    pthread_create(&tid, NULL, printprime, (void *)NULL);

    pthread_join(tid, NULL);

    for (count = 0; count < N; count++)
        if (prime_arr[count] == 1) printf("%d ", count);

    return 0;
}
